				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$e_{ij}^{\left( 1 \right)} = LeakyReLU\left( {a^{\left( 1 \right)T} \left[ {{W}^{\left( 1 \right)} h_{i}^{\left( 0 \right)} ||{W}^{\left( 1 \right)} h_{j}^{\left( 0 \right)} } \right]} \right)$$\end{document}eij1=LeakyReLUa1TW1hi0||W1hj04\documentclass[12pt]{minimal}
				\usepackage{amsmath}
				\usepackage{wasysym} 
				\usepackage{amsfonts} 
				\usepackage{amssymb} 
				\usepackage{amsbsy}
				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$\alpha_{ij}^{\left( 1 \right)} = \frac{{\exp \left( {e_{ij}^{\left( 1 \right)} } \right)}}{{\sum\limits_{k \in N\left( i \right)} {\exp \left( {e_{ik}^{\left( 1 \right)} } \right)} }}$$\end{document}αij1=expeij1∑k∈Niexpeik1

W(1) is the trainable weight matrix, \documentclass[12pt]{minimal}
